// Explicit — targets your own DetailsActivity directly
startActivity(Intent(this, DetailsActivity::class.java))

// Implicit — system finds any app that can view this URL
startActivity(Intent(Intent.ACTION_VIEW, Uri.parse("https://example.com")))

val intent = Intent(context, MainActivity::class.java).apply {
    flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP
}
context.startActivity(intent) // context here is not an Activity — NEW_TASK required

// Dynamic — tied to this Activity's lifecycle
override fun onStart() {
    super.onStart()
    registerReceiver(myReceiver, IntentFilter("com.example.ACTION"))
}
override fun onStop() { super.onStop(); unregisterReceiver(myReceiver) }

// Deprecated:
// LocalBroadcastManager.getInstance(context).sendBroadcast(intent)

// Preferred — in-process event stream:
object AppEvents { val bus = MutableSharedFlow<AppEvent>(extraBufferCapacity = 8) }
AppEvents.bus.tryEmit(AppEvent.UserLoggedIn)

// In a library module's manifest, declaring:
<uses-permission android:name="android.permission.INTERNET" />
// automatically merges into the final app manifest, even if the app module never declared it itself

android {
    compileSdk = 35 // build-time API surface, no runtime effect
    defaultConfig {
        minSdk = 24     // oldest installable OS version
        targetSdk = 34  // which version's runtime behavior the app opts into
    }
}

// Started — runs independently once launched
context.startService(Intent(context, SyncService::class.java))

// Bound — tied to the connection's lifetime
context.bindService(intent, connection, Context.BIND_AUTO_CREATE)

class SyncWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {
    override suspend fun doWork(): Result {
        return try { performSync(); Result.success() } catch (e: Exception) { Result.retry() }
    }
}

WorkManager.getInstance(context).enqueue(OneTimeWorkRequestBuilder<SyncWorker>().build())

override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
    performWork(intent)
    return START_REDELIVER_INTENT // needs the original Intent's data to resume correctly
}

// Throws IllegalStateException if the app is in the background on API 26+:
// context.startService(Intent(context, MyService::class.java))

// Reliable alternatives:
WorkManager.getInstance(context).enqueue(workRequest) // deferred, constraint-aware
ContextCompat.startForegroundService(context, intent) // immediate, user-visible

class LocalBinder(val service: MyService) : Binder()

val connection = object : ServiceConnection {
    override fun onServiceConnected(name: ComponentName, binder: IBinder) {
        val myService = (binder as LocalBinder).service // direct method access, same process
    }
    override fun onServiceDisconnected(name: ComponentName) { }
}

class SyncService : Service() {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        scope.launch { performSync() } // explicitly off the main thread
        return START_NOT_STICKY
    }
}
